                               relief: it.relief && maps !== 'own' ? { sign: it.relief === 'raise' ? 'up' : 'down', depth: (it.depth || 40) / 100, floors: it.floors === 'keep' ? 'keep' : 'smooth', relief: whiteOf(body), hole: whiteOf(k) } : null,
