        TL: ['TL', 0], TR: ['TL', 1], BR: ['TL', 2], BL: ['TL', 3],
        ITL: ['ITL', 0], ITR: ['ITL', 1], IBR: ['ITL', 2], IBL: ['ITL', 3],
        C: ['C', 0]
