        organic:  { label: 'Organic (wood, grass, skin, cloth)', r: { sharpen: 25, selfex: 70, grain: 0, contours: 0, guided: false } },
        smooth:   { label: 'Smooth (metal, glass, plastic)', r: { sharpen: 30, selfex: 0, grain: 0, contours: 0, guided: true } },
