        $('at-hd-paint').style.display = on ? 'block' : 'none'; $('at-hd-paint-label').style.display = on ? '' : 'none';
        $('at-hd-before').style.display = on ? 'none' : 'block'; $('at-hd-before-label').style.display = on ? 'none' : '';
