        sbNumRow($('at-hd-rows'), ['sharpen', 'Edge sharpening', 0, 100, 1, 0, '%'], 'hd', hdTouch);
        sbNumRow($('at-hd-rows'), ['selfex', 'Detail from the tile itself', 0, 100, 1, 0, '%'], 'hd', hdTouch);
