        $('at-st-x').value = Math.round((it.cx - it.w / 2) * 100) / 100; $('at-st-y').value = Math.round((it.cy - it.h / 2) * 100) / 100;
        $('at-st-w').value = it.w; $('at-st-h').value = it.h;
